import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
ALLOWED_EXTENSIONS = {'yaml', 'yml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_schema(data):
    """Basic schema validation for report configs"""
    required = ['report_name', 'author', 'template']
    return all(k in data for k in required)

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from YAML configuration"""
    if 'config' not in request.files:
        return jsonify({'error': 'No config file provided'}), 400

    config_file = request.files['config']
    if not allowed_file(config_file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    filename = secure_filename(config_file.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    config_file.save(filepath)

    try:
        with open(filepath, 'r') as f:
            config = yaml.safe_load(f)

        if not validate_schema(config):
            return jsonify({'error': 'Invalid schema'}), 400

        template_name = config['template']
        output_name = config['report_name']

        # Sanitize output name
        output_name = output_name.replace('/', '_').replace('\\', '_')
        output_path = os.path.join(UPLOAD_DIR, f"{output_name}.pdf")

        # Build wkhtmltopdf command from template
        template_path = f"/app/templates/{template_name}"
        cmd = f"wkhtmltopdf --enable-local-file-access {template_path} {output_path}"

        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd='/app'
        )

        if result.returncode != 0:
            return jsonify({'error': 'Generation failed', 'detail': result.stderr.decode()[:200]}), 500

        file_hash = hashlib.sha256(open(output_path, 'rb').read()).hexdigest()
        return jsonify({
            'status': 'success',
            'output': f"/reports/{output_name}.pdf",
            'sha256': file_hash
        })
    except yaml.YAMLError as e:
        return jsonify({'error': f'YAML parse error: {str(e)}'}), 400
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Generation timeout'}), 504
    finally:
        if os.path.exists(filepath):
            os.unlink(filepath)

@app.route('/api/v1/reports/preview', methods=['POST'])
def preview_report():
    """Preview report metadata without generating"""
    if 'config' not in request.files:
        return jsonify({'error': 'No config file'}), 400

    config_file = request.files['config']
    content = config_file.read()

    try:
        config = yaml.safe_load(content)
        if not validate_schema(config):
            return jsonify({'error': 'Invalid schema'}), 400
        return jsonify({
            'report_name': config['report_name'],
            'author': config['author'],
            'template': config['template'],
            'sections': config.get('sections', [])
        })
    except yaml.YAMLError as e:
        return jsonify({'error': str(e)}), 400

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
